"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[8545],{35078(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>s,metadata:()=>r,toc:()=>h});var i=n(74848),o=n(28453);const s={title:"Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence",date:new Date("2026-08-06T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"platform-silencing",article_tags:{zh:["\u5e73\u53f0\u58df\u65b7","\u6f14\u7b97\u6cd5\u6cbb\u7406","\u5167\u5bb9\u5be9\u67e5","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31","\u7126\u616e\u5957\u5229"],en:["platform-monopoly","algorithmic-governance","content-moderation","information-asymmetry","anxiety-arbitrage"]},keywords:["Patent 10356024","demotion","content distribution guidelines","DSA Article 17","manufactured consensus"],summary:"Demotion is not a gentler version of censorship \u2014 it is attenuation designed to produce no evidence.",status:"final",reading_time:19,series:{id:"attenuation-visibility",name:"Attenuation: How Visibility Is Allocated",order:1,total:3}},a="Approved, Then Unseen",r={id:"TechNotes/\u6279\u51c6\u4e4b\u5f8c\u6c92\u6709\u4eba\u770b\u898b",title:"Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence",description:"Author: Nebula Walker",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/01-\u6279\u51c6\u4e4b\u5f8c\u6c92\u6709\u4eba\u770b\u898b.md",sourceDirName:"TechNotes",slug:"/TechNotes/\u6279\u51c6\u4e4b\u5f8c\u6c92\u6709\u4eba\u770b\u898b",permalink:"/en/docs/TechNotes/\u6279\u51c6\u4e4b\u5f8c\u6c92\u6709\u4eba\u770b\u898b",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:1,frontMatter:{title:"Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence",date:"2026-08-06T00:00:00.000Z",lang:"en",section:"sober-record",topic:"platform-silencing",article_tags:{zh:["\u5e73\u53f0\u58df\u65b7","\u6f14\u7b97\u6cd5\u6cbb\u7406","\u5167\u5bb9\u5be9\u67e5","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31","\u7126\u616e\u5957\u5229"],en:["platform-monopoly","algorithmic-governance","content-moderation","information-asymmetry","anxiety-arbitrage"]},keywords:["Patent 10356024","demotion","content distribution guidelines","DSA Article 17","manufactured consensus"],summary:"Demotion is not a gentler version of censorship \u2014 it is attenuation designed to produce no evidence.",status:"final",reading_time:19,series:{id:"attenuation-visibility",name:"Attenuation: How Visibility Is Allocated",order:1,total:3}},sidebar:"docs",previous:{title:"Lucid Record",permalink:"/en/docs/TechNotes/"},next:{title:'Did Jensen Huang Say "Liberal Arts Students Won"? You Got Fooled by the Clickbait.',permalink:"/en/docs/TechNotes/NvidaAllInPodcast"}},l={},h=[{value:"I. An Afternoon That Left No Trace",id:"i-an-afternoon-that-left-no-trace",level:2},{value:"II. Only a Matter of Degree",id:"ii-only-a-matter-of-degree",level:2},{value:"III. Patent 10356024",id:"iii-patent-10356024",level:2},{value:"IV. The More Common Version: No One Needs to Press a Button",id:"iv-the-more-common-version-no-one-needs-to-press-a-button",level:2},{value:"V. The Third Layer: Dissent Appears as &quot;Non-Existence&quot;",id:"v-the-third-layer-dissent-appears-as-non-existence",level:2},{value:"VI. This Is Why Scams Move Faster",id:"vi-this-is-why-scams-move-faster",level:2},{value:"VII. What Meta Itself Wrote",id:"vii-what-meta-itself-wrote",level:2},{value:"VIII. The Company That Can Demote with Precision Claims It Can&#39;t Identify Content Farms",id:"viii-the-company-that-can-demote-with-precision-claims-it-cant-identify-content-farms",level:2},{value:"IX. The Shelf-Fee Analogy, and Why It Doesn&#39;t Hold",id:"ix-the-shelf-fee-analogy-and-why-it-doesnt-hold",level:2},{value:"X. The Cruellest Part Is Not Silencing \u2014 It&#39;s Exploitation",id:"x-the-cruellest-part-is-not-silencing--its-exploitation",level:2},{value:"XI. Two Things I Cannot Claim",id:"xi-two-things-i-cannot-claim",level:2},{value:"XII. You&#39;re Not the Only One Who Won&#39;t Be Counted",id:"xii-youre-not-the-only-one-who-wont-be-counted",level:2},{value:"XIII. If You Want to Self-Verify",id:"xiii-if-you-want-to-self-verify",level:2},{value:"XIV. The Inversion of the Burden of Proof",id:"xiv-the-inversion-of-the-burden-of-proof",level:2},{value:"Sources",id:"sources",level:2},{value:"This Series",id:"this-series",level:2}];function c(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"Author: Nebula Walker\nDate: 06AUG2026\nMYTHOGEN ENGINE (mythogenengine.com)"}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"approved-then-unseen",children:"Approved, Then Unseen"})}),"\n",(0,i.jsx)(t.h2,{id:"i-an-afternoon-that-left-no-trace",children:"I. An Afternoon That Left No Trace"}),"\n",(0,i.jsx)(t.p,{children:"The post was submitted for review. It was approved. The admin even liked it."}),"\n",(0,i.jsx)(t.p,{children:"You scroll into the group. The post is there \u2014 formatting intact, timestamp normal. Three hours later, the reach counter stalls at twenty-four. The page status says no issues. The account has no restrictions. The violation record reads zero."}),"\n",(0,i.jsx)(t.p,{children:"So you arrive at the only possible conclusion: you didn't write well enough."}),"\n",(0,i.jsx)(t.p,{children:"Until you borrow someone else's account and log in. They scroll through the entire group. Your post is nowhere to be found."}),"\n",(0,i.jsx)(t.p,{children:"Up to that moment, the only \"evidence\" you had was the absence of response. And absence of response, in any appeals process, does not constitute evidence \u2014 it doesn't even constitute a problem. Because the system's default explanation is always ready, always reasonable, and always points back at you."}),"\n",(0,i.jsx)(t.p,{children:"What I want to discuss is not how demoralising this is. What I want to discuss is this: this state of affairs is not an accident, nor a side-effect of the algorithm. It is an invention \u2014 with a number, an applicant, and an approval date."}),"\n",(0,i.jsx)(t.h2,{id:"ii-only-a-matter-of-degree",children:"II. Only a Matter of Degree"}),"\n",(0,i.jsx)(t.p,{children:"First, let's dismantle a false premise."}),"\n",(0,i.jsx)(t.p,{children:'Every argument about "whether or not censorship occurred" assumes that censorship is a discrete event: blocked or not, deleted or not, yes or no. People argue about whether the switch was flipped.'}),"\n",(0,i.jsx)(t.p,{children:"But the platform doesn't hold a switch. It holds a dial \u2014 a continuous one."}),"\n",(0,i.jsx)(t.p,{children:"Blocking an account is turning the dial to zero. Rejecting a post is turning it to ten percent. Approving but not distributing is turning it to twenty percent. Doing nothing and letting the ranking system handle it is turning it to some number that nobody needs to be accountable for."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"The effects belong to the same category. They differ only in degree."})}),"\n",(0,i.jsxs)(t.p,{children:["And this is precisely the advantage of a continuous dial: ",(0,i.jsx)(t.strong,{children:"no event means no evidence."})]}),"\n",(0,i.jsx)(t.p,{children:"A discrete action produces a timestamp, a notification, an identifiable subject. Continuous attenuation produces nothing. Same outcome \u2014 one requires accountability, the other doesn't."}),"\n",(0,i.jsxs)(t.p,{children:["So the more precise term isn't censorship. It's ",(0,i.jsx)(t.strong,{children:"attenuation"}),". This is not a loophole. It's a chosen design."]}),"\n",(0,i.jsx)(t.p,{children:"Deletion produces three things: a point in time, a notification that can be screenshotted, and a narrative that can be told."}),"\n",(0,i.jsx)(t.p,{children:"Demotion produces none."}),"\n",(0,i.jsx)(t.p,{children:"No point in time, so you don't know when it began. No notification, so there's no entity to appeal to. No narrative, so you can't explain to anyone what happened \u2014 all you can say is \"not many people seem to have seen it,\" and that sounds like a complaint, not an accusation."}),"\n",(0,i.jsx)(t.p,{children:"A person who's been deleted can say, \"I was deleted.\" That sentence has a subject, a verb, and an object. It can be verified; it can be refuted. A person who's been demoted can't even form a complete sentence."}),"\n",(0,i.jsx)(t.p,{children:"So deletion is more merciful. At least it acknowledges you existed."}),"\n",(0,i.jsx)(t.h2,{id:"iii-patent-10356024",children:"III. Patent 10356024"}),"\n",(0,i.jsx)(t.p,{children:'Filed in February 2015. Granted by the United States Patent and Trademark Office in July 2019. Title: "Moderating content in an online forum." Applicant: Facebook.'}),"\n",(0,i.jsxs)(t.p,{children:["In plain language, the abstract says this: the system can receive a list of prohibited content and block it by ",(0,i.jsx)(t.strong,{children:"reducing the distribution of those comments to other viewers"}),", while ",(0,i.jsx)(t.strong,{children:"still displaying the blocked content to the user who posted it"}),", so that the user ",(0,i.jsx)(t.strong,{children:"will not realise"})," they have been blocked."]}),"\n",(0,i.jsx)(t.p,{children:"Three actions, composing a single mechanism:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsx)(t.li,{children:"Reduce distribution to others"}),"\n",(0,i.jsx)(t.li,{children:"Maintain normal display to the author"}),"\n",(0,i.jsx)(t.li,{children:"Stated purpose: to prevent the author from knowing"}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:['The first two are engineering. The third is the patent\'s actual claimed invention \u2014 not "how to restrict distribution," but ',(0,i.jsx)(t.strong,{children:"how to make the restricted person feel as though they are not restricted"}),". This statement was written into the application as a technical feature and was granted."]}),"\n",(0,i.jsx)(t.p,{children:'The patent also extends this capability to "forum creators or moderators," and it can be executed automatically by text sentiment analysis or machine-learning classifiers. In other words, from its inception, this was never just a platform-level anti-spam tool. It is a power designed to be delegated to community administrators.'}),"\n",(0,i.jsx)(t.p,{children:'To be clear: a granted patent does not mean deployment. Nor does it mean that every instance of silence you encounter traces back to this code. I will not make that accusation. But a patent records intent and method \u2014 ten years ago, a group of engineers sat down and defined "making the user unaware" as a technical problem worth filing and worth protecting. That fact alone says a great deal.'}),"\n",(0,i.jsxs)(t.p,{children:["This logic was not confined to the distribution layer. When the same principle \u2014 no announcement, no record, no notification \u2014 was carried to the criteria layer \u2014 deciding what counts as good content, what counts as machine-written \u2014 the detector ended up manufacturing the very thing it claimed to detect. That is the subject of Volume II of this series (",(0,i.jsx)(t.em,{children:"The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots"}),")."]}),"\n",(0,i.jsx)(t.p,{children:"And the real intersection of the two layers is this: they operate independently, yet they penalise the same behaviour. Careful revision produces clean, consistent text \u2014 which is precisely what the detector flags as machine-generated. Careful revision also produces long-form writing, outbound links, and low emotional arousal \u2014 which are precisely the features that the content distribution guidelines explicitly list for demotion. Two machines that have never met, yet they always land on the same person."}),"\n",(0,i.jsx)(t.p,{children:"There is also a question of timing worth noting separately."}),"\n",(0,i.jsx)(t.p,{children:"This patent was filed in 2015 and granted in 2019. Generative AI entered the public consciousness from late 2022 onward."}),"\n",(0,i.jsx)(t.p,{children:'That is to say, "reducing distribution while keeping the author unaware" predates the technology now being scapegoated by at least seven years. It is not a model error. It is not training-data bias. It is not anything that can be explained away as "the technology isn\'t mature yet." It was conceived, documented, and paid to be protected before deep learning was widely deployed for content ranking.'}),"\n",(0,i.jsx)(t.p,{children:"Attributing it to algorithmic misjudgement is a very convenient mistake. Because algorithms have no motive, and mistakes can be fixed \u2014 as long as the problem is framed as a technical issue, it automatically becomes something that will eventually be resolved, and no one needs to be held responsible."}),"\n",(0,i.jsxs)(t.p,{children:["But a patent is not a misjudgement. A patent is something that someone sat down, thought through, wrote into a document, and paid to protect. ",(0,i.jsx)(t.strong,{children:"That is a decision, and the nature of the decision is commercial."})]}),"\n",(0,i.jsx)(t.p,{children:"In this matter, the algorithm is the executor, not the decision-maker. Putting the executor on trial lets the real defendant carry on with their meetings."}),"\n",(0,i.jsx)(t.h2,{id:"iv-the-more-common-version-no-one-needs-to-press-a-button",children:"IV. The More Common Version: No One Needs to Press a Button"}),"\n",(0,i.jsx)(t.p,{children:"The truly everyday form is far milder than the patent, and far harder to address."}),"\n",(0,i.jsxs)(t.p,{children:["Meta's own transparency pages explain that each group's individual News Feed is an AI-based ranking system: it scores each post, ranks them by score, and factors in your typical interaction patterns with that group. The same page also states that group administrators can ",(0,i.jsx)(t.strong,{children:"set a default sorting method that applies to all members and visitors"}),"."]}),"\n",(0,i.jsx)(t.p,{children:"This creates a perfectly legal, perfectly traceless operation: approve your post, even like it, then do nothing."}),"\n",(0,i.jsxs)(t.p,{children:["Approval only makes the post exist in the database. ",(0,i.jsx)(t.strong,{children:"Existence does not equal distribution."})]}),"\n",(0,i.jsx)(t.p,{children:"If the administrator runs courses, cheat sheets, or tool lists, they don't need to suppress anyone. They only need to keep the default sort on \"Most Relevant\" and ensure that their inner circle's content gets early engagement \u2014 pinning, cross-promotion, opening comments \u2014 and outsiders will sink to the bottom automatically. Every single action, viewed in isolation, is legitimate community management."}),"\n",(0,i.jsx)(t.p,{children:"Stacked together, the effect is identical to the patent. The only difference: no one did anything wrong."}),"\n",(0,i.jsxs)(t.p,{children:["This is the most refined aspect of the system. ",(0,i.jsx)(t.strong,{children:"It doesn't need a villain."})]}),"\n",(0,i.jsxs)(t.p,{children:["And therefore, questioning intent is pointless. I cannot prove any administrator's motive, nor do I need to \u2014 because in this structure, ",(0,i.jsx)(t.strong,{children:"the outcome does not depend on intent"}),". Self-interested management behaviour and deliberate exclusion output the same News Feed."]}),"\n",(0,i.jsx)(t.h2,{id:"v-the-third-layer-dissent-appears-as-non-existence",children:'V. The Third Layer: Dissent Appears as "Non-Existence"'}),"\n",(0,i.jsx)(t.p,{children:'Everything discussed so far has been about "voices being turned down." But that is only the first-order effect.'}),"\n",(0,i.jsx)(t.p,{children:"A group administrator effectively controls three things:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Who gets to speak"})," \u2014 review, approval, delay"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Which content rises to the top"})," \u2014 default sorting, pinning, early engagement"]}),"\n",(0,i.jsx)(t.li,{children:(0,i.jsx)(t.strong,{children:"Which opinion appears to be everyone's opinion"})}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The third layer requires no additional action. It is the automatic product of the first two layers combined \u2014 and it is the real output."}),"\n",(0,i.jsxs)(t.p,{children:['Because after suppressing ten dissenters, what remains is not "ninety supporters plus ten silent people." It is a ',(0,i.jsx)(t.strong,{children:"room that looks entirely unanimous"}),'. Every person in that room calibrates their own judgement against "no one disagrees."']}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:'Dissent does not appear as "dissent." It appears as "non-existence."'})}),"\n",(0,i.jsx)(t.p,{children:"And non-existence reads as agreement. You cannot be suspicious of an empty chair."}),"\n",(0,i.jsx)(t.p,{children:"So the mechanism's output is not silencing. It is consensus. And consensus is something that can be manufactured, traded, and is extremely valuable."}),"\n",(0,i.jsx)(t.h2,{id:"vi-this-is-why-scams-move-faster",children:"VI. This Is Why Scams Move Faster"}),"\n",(0,i.jsx)(t.p,{children:'The investment fraud methods published by Taiwan\'s Criminal Investigation Bureau and local police departments follow a fixed structure: social media ads attract users to join a group; group members play multiple roles; "plants" post profit screenshots to create an atmosphere where everyone is winning; early small withdrawals build trust; after larger investments, withdrawal is refused on grounds of tax or bond payments; anyone who starts to question is immediately kicked out.'}),"\n",(0,i.jsx)(t.p,{children:"Map each of these actions back to the three layers of control from the previous section. They match perfectly."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"The difference is not in the technology. It's in the disclosure."})}),"\n",(0,i.jsx)(t.p,{children:"What a fraud ring needs \u2014 a trust machine \u2014 is simply a controlled group: controlling who speaks, controlling what rises, controlling what looks like consensus. They don't need to build this machine themselves \u2014 the platform ships it as a standard feature to every moderator."}),"\n",(0,i.jsxs)(t.p,{children:["So a course-selling administrator and a fraud-running syndicate use ",(0,i.jsx)(t.strong,{children:"the same default settings"}),". The former sells anxiety relief; the latter sells the evaporation of capital. Same architecture, different price tier."]}),"\n",(0,i.jsx)(t.p,{children:"This also explains something that puzzled me for a long time: why structural analysis fails to cool the frenzy inside these groups. Because those people aren't information-deprived \u2014 the room they're in has already been calibrated for unanimity. In a space where all opposing views appear as \"non-existence,\" an article saying \"that's not how it works\" doesn't read as a correction. It reads as noise."}),"\n",(0,i.jsx)(t.h2,{id:"vii-what-meta-itself-wrote",children:"VII. What Meta Itself Wrote"}),"\n",(0,i.jsxs)(t.p,{children:["The EU Digital Services Act requires platforms to submit transparency reports. Meta's version includes a note, stated very clearly: ",(0,i.jsx)(t.strong,{children:"demoted content does not necessarily violate Community Standards"}),'; therefore, demotion actions are classified under "content distribution guidelines," not under violation records.']}),"\n",(0,i.jsx)(t.p,{children:"This single sentence explains the seemingly contradictory picture:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"Page status: no issues"}),"\n",(0,i.jsx)(t.li,{children:"Account restrictions: none"}),"\n",(0,i.jsx)(t.li,{children:"Violation record: zero"}),"\n",(0,i.jsx)(t.li,{children:"Average reach: twenty-four"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"There's no contradiction. Because demotion doesn't go through the violation system at all. It writes to no panel you can see, so your account stays permanently clean while your voice never arrives."}),"\n",(0,i.jsx)(t.p,{children:"You thought you were reading a health report. You were actually reading a health report that doesn't include that particular test."}),"\n",(0,i.jsx)(t.p,{children:"The Digital Services Act, Article 17, stipulates: for any visibility restriction \u2014 and the text explicitly includes demotion \u2014 the platform must provide the affected user with a clear and specific statement of reasons."}),"\n",(0,i.jsx)(t.p,{children:"Same company, same system, same algorithm. In the EU, they must inform you. In Taiwan, in Hong Kong \u2014 they don't have to."}),"\n",(0,i.jsx)(t.p,{children:"That sentence is worth pausing on."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"It's not that they can't. It's that they don't have to."})}),"\n",(0,i.jsx)(t.p,{children:'Every claim of "we can\'t distinguish," "the scale is too large," "it\'s technically difficult" is instantly invalidated by an enforceable regulation. Technical feasibility was never the issue. It never was.'}),"\n",(0,i.jsx)(t.h2,{id:"viii-the-company-that-can-demote-with-precision-claims-it-cant-identify-content-farms",children:"VIII. The Company That Can Demote with Precision Claims It Can't Identify Content Farms"}),"\n",(0,i.jsx)(t.p,{children:"Place this back in a commercial context to see the full picture."}),"\n",(0,i.jsx)(t.p,{children:"In November 2025, Reuters reported, based on a batch of internal documents: Meta internally estimated that approximately ten percent of its 2024 revenue \u2014 roughly USD 16 billion \u2014 came from scam and contraband advertising; the platform was pushing approximately 15 billion high-risk scam ads daily, annualising to about USD 7 billion in revenue."}),"\n",(0,i.jsx)(t.p,{children:"The enforcement threshold was designed as follows: the automated system required 95% confidence to block a suspected scam advertiser; below that threshold, the suspected party was not blocked but charged a higher advertising fee. In the first half of 2025, the ad integrity team was instructed that no enforcement action could cut more than 0.15% of projected revenue \u2014 a maximum of USD 135 million out of USD 90 billion. A separate internal document estimated the regulatory fine ceiling at approximately USD 1 billion, noting it was far lower than scam-ad revenue."}),"\n",(0,i.jsx)(t.p,{children:"Meta subsequently responded that the ten-percent revenue figure was an internal one-off rough estimate using overly broad criteria and should not be treated as an actual figure. This rebuttal should be included, because it doesn't actually undermine the argument \u2014 it only undermines the total amount."}),"\n",(0,i.jsx)(t.p,{children:"The two truly fatal items are not estimates. They are directives: the 95% blocking threshold, and the enforcement cap at 0.15% of revenue. Estimates can be debated on methodology; directives have no methodology to debate."}),"\n",(0,i.jsx)(t.p,{children:"And the same company's content distribution guidelines list, in black and white, the types of content subject to demotion: content with limited originality that mainly repackages from other sources; clickbait and engagement bait; links to ad-heavy, slow-loading websites."}),"\n",(0,i.jsx)(t.p,{children:"That description is the definition of a content farm. The rule exists but doesn't trigger."}),"\n",(0,i.jsx)(t.p,{children:"So we get a clean comparison:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"For a long-form article: demotion is precise, instant, requires no reason, no notification, no record."}),"\n",(0,i.jsx)(t.li,{children:"For a scam ad: requires 95% confidence, and enforcement has a budget cap."}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"A company capable of the former, claiming it cannot do the latter \u2014 that statement is logically untenable."}),"\n",(0,i.jsx)(t.p,{children:"It's not a capability problem. It's an allocation problem. The capacity for precision demotion has always existed. It just isn't applied to the paying side."}),"\n",(0,i.jsx)(t.h2,{id:"ix-the-shelf-fee-analogy-and-why-it-doesnt-hold",children:"IX. The Shelf-Fee Analogy, and Why It Doesn't Hold"}),"\n",(0,i.jsx)(t.p,{children:"At this point, the most common defence will appear: isn't this just shelf fees in a supermarket?"}),"\n",(0,i.jsx)(t.p,{children:"Good placement costs money. Eye-level shelves cost more than the bottom row. Endcaps cost more than mid-aisle facings. Those who can pay get the front; those who can't get the corner. This has been normal commercial practice for decades, and no one thinks it calls for outrage."}),"\n",(0,i.jsx)(t.p,{children:"This analogy deserves serious engagement, because it isn't frivolous \u2014 retailers do sell visibility, and platforms do too. But there are three differences, and every one of them lands in the same place."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"First, shelves are visible."})}),"\n",(0,i.jsx)(t.p,{children:"A supplier walks into the store and immediately knows they've been placed on the bottom shelf. They don't need to borrow someone else's membership card, control for variables, or compare screenshots from two devices. They look down and they know. Demotion is visible to the naked eye, occurring in broad daylight."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Second, there is a price list and a receipt."})}),"\n",(0,i.jsx)(t.p,{children:"Shelf fees are negotiated. There is a quote, a contract, and a clear exchange: you pay this amount, you get this placement. Afterward, both parties know what happened, because it was a documented transaction."}),"\n",(0,i.jsx)(t.p,{children:"On the platform side, no such document exists. No one quotes you \"pay this and your post will be visible to group members.\" When you're moved to a lower tier, no document is generated. This isn't a cheaper version \u2014 this is a version where the transaction doesn't even exist."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Third, the rejected party knows they were rejected."})}),"\n",(0,i.jsx)(t.p,{children:"A supplier who fails to secure shelf space will know. They can count, they can negotiate, they can file a complaint, they can try a different chain, they can tell others about it \u2014 because they have an event they can narrate."}),"\n",(0,i.jsx)(t.p,{children:"And this is exactly what the preceding sections have repeatedly described: a demoted person does not have this awareness. They don't even know which group they belong to."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"There is also a commonly overlooked difference on the buyer's side."})}),"\n",(0,i.jsx)(t.p,{children:"The customer can see the shelf too. They know the bottom row exists; if they want to find something, they squat down and they can. The entire store's inventory is in front of them \u2014 the only difference is ease of access."}),"\n",(0,i.jsx)(t.p,{children:"A News Feed has no bottom shelf. You can't squat down, because that space simply doesn't exist \u2014 undistributed content, to the reader, is not hard to reach. It's non-existent."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"So the real difference isn't whether you charge. It's whether visibility itself is visible."})}),"\n",(0,i.jsx)(t.p,{children:"A supermarket sells good placement, and all placements are visible. A platform sells visibility, and the allocation of visibility is itself invisible."}),"\n",(0,i.jsx)(t.p,{children:"One is a market where fairness can be debated. The other doesn't even generate the information required for that debate."}),"\n",(0,i.jsx)(t.h2,{id:"x-the-cruellest-part-is-not-silencing--its-exploitation",children:"X. The Cruellest Part Is Not Silencing \u2014 It's Exploitation"}),"\n",(0,i.jsx)(t.p,{children:"What truly stings is not having your article deleted. It's having someone praise your content while knowing that most people will never see it."}),"\n",(0,i.jsx)(t.p,{children:"In this structure, an administrator doesn't need to refute you, block you, or even dislike you. They only need to let you keep writing."}),"\n",(0,i.jsx)(t.p,{children:'And by continuing to write, you provide more than articles. You provide content density for the group, activity metrics for the platform, training signals for the recommendation system, indexing material for search engines, and the brand value of "this group has many quality creators." Only your reach \u2014 your influence \u2014 does not increase.'}),"\n",(0,i.jsxs)(t.p,{children:["This produces a peculiar state: ",(0,i.jsx)(t.strong,{children:"the system still needs you to create. It just doesn't need anyone to see you."})]}),"\n",(0,i.jsx)(t.p,{children:"Here I must again hold the line: I cannot claim that anyone knowingly exploited you while aware of your suppression. I don't have that evidence, and this article will not pretend to."}),"\n",(0,i.jsxs)(t.p,{children:["But even without that evidence, this remains true \u2014 because the structure makes the following scenario possible: ",(0,i.jsx)(t.strong,{children:"even if an administrator genuinely admires your content and even likes your posts, as long as they don't actively change the distribution settings, you will remain a creator who contributes value long-term yet remains invisible long-term."})]}),"\n",(0,i.jsx)(t.p,{children:"Asymmetry doesn't need malice to sustain itself. It only needs no one to make a change."}),"\n",(0,i.jsx)(t.p,{children:"And once this asymmetry stabilises, the relationship among the group operator, the platform, and the creator becomes one of unilateral benefit \u2014 not because anyone decided to exploit anyone, but because changing it offers no advantage to the only party with the power to do so."}),"\n",(0,i.jsx)(t.h2,{id:"xi-two-things-i-cannot-claim",children:"XI. Two Things I Cannot Claim"}),"\n",(0,i.jsx)(t.p,{children:"At this point, I must apply the brakes myself. An article about the burden of proof cannot be supported by accusations that cannot be proven."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"First, I cannot claim any specific person did anything."})," All the mechanisms above have public documentation: the patent, transparency pages, statutory provisions, transparency reports. But who pressed what in which group \u2014 I have no evidence, and this article will not pretend to. The strength of structural analysis lies precisely in not needing to name names \u2014 when a system makes self-interest and malice produce the same outcome, asking which one occurred is itself a designed detour."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:'Second, I cannot claim that "if distribution were fair, things would be different."'})," There are actually two independent constraints here, and conflating them leads to a false conclusion."]}),"\n",(0,i.jsx)(t.p,{children:"One is distribution attenuation \u2014 real, verifiable, and the platform's responsibility."}),"\n",(0,i.jsx)(t.p,{children:"The other is demand mismatch: an article asking readers to admit they can't judge and an ad promising readers they don't need to judge are simply not competing in the same market. The former sells cognitive cost; the latter sells cognitive exemption. Even if the channel were perfectly fair, the latter would still win that room."}),"\n",(0,i.jsx)(t.p,{children:'Separating the two explains why "extremely high completion rate" and "extremely low reach" can coexist \u2014 because they aren\'t even the same cohort.'}),"\n",(0,i.jsx)(t.h2,{id:"xii-youre-not-the-only-one-who-wont-be-counted",children:"XII. You're Not the Only One Who Won't Be Counted"}),"\n",(0,i.jsx)(t.p,{children:"There's one more thing I realised very late."}),"\n",(0,i.jsx)(t.p,{children:'I learned that "many people have already stopped using Facebook" not from any data, but from someone mentioning it in an offline class.'}),"\n",(0,i.jsx)(t.p,{children:"This wasn't luck. It's structure."}),"\n",(0,i.jsxs)(t.p,{children:["No one posts \"I'm quitting.\" Even if they did, the algorithm wouldn't surface it for you. And an account that has stopped posting appears exactly the same as one that never existed, in your News Feed. ",(0,i.jsx)(t.strong,{children:"The system you inhabit is physically incapable of telling you how many people have left."})]}),"\n",(0,i.jsxs)(t.p,{children:["From this, a rule can be derived: ",(0,i.jsx)(t.strong,{children:"information about platform attrition can only propagate through non-platform channels."})," Those who remain, no matter how they count, can never count those who have already gone."]}),"\n",(0,i.jsx)(t.p,{children:"This point is two sides of the same coin as all the mechanisms above. The system doesn't just make your voice invisible. It also makes others' departure invisible. You're left in a room that still looks busy \u2014 and the busyness itself is the final layer of manufactured consensus."}),"\n",(0,i.jsx)(t.p,{children:"And the demoted person's situation is exactly the same."}),"\n",(0,i.jsx)(t.p,{children:"Deletion can be counted. Each deletion has a subject, a timestamp, a notification \u2014 so it can be tallied, aggregated, written into reports, and eventually compressed into a number. And numbers create pressure."}),"\n",(0,i.jsx)(t.p,{children:"Demotion has none of these. No one receives a notification, so no one knows which group they belong to. And a group whose members don't know they're in it will never organise, never speak out, and never become an issue."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Victims who cannot be counted are, institutionally, non-existent."})}),"\n",(0,i.jsx)(t.p,{children:"Not denied \u2014 simply ineligible for counting. Counting requires a list, and this mechanism's design purpose is precisely to produce no list."}),"\n",(0,i.jsx)(t.p,{children:"No list means no group. No group means no demands. No demands means no policy pressure. The chain breaks at the very first link."}),"\n",(0,i.jsxs)(t.p,{children:["This is also why compressing a society's public discourse today no longer requires any censorship apparatus. ",(0,i.jsx)(t.strong,{children:"All it takes is ensuring that the affected people cannot recognise each other."})]}),"\n",(0,i.jsx)(t.h2,{id:"xiii-if-you-want-to-self-verify",children:"XIII. If You Want to Self-Verify"}),"\n",(0,i.jsx)(t.p,{children:"A few practical words for those who still want to document what's happening."}),"\n",(0,i.jsx)(t.p,{children:'The second account must already be a group member, using a different device and network, and must not be friends with you \u2014 the friend relationship independently boosts ranking. Open both simultaneously. Switch both to "Newest Posts" (chronological order) to eliminate ranking as a variable. If chronological shows the post but "Most Relevant" doesn\'t, the restriction is at the ranking layer. If neither shows it, the restriction is at the distribution layer. Screenshots must include the clock and scroll position; timestamps on both sides must match. Simultaneously post a control \u2014 short, no outbound links, non-controversial \u2014 and compare performance over the same period.'}),"\n",(0,i.jsx)(t.p,{children:"After all this, you'll have a record that can convince yourself."}),"\n",(0,i.jsx)(t.p,{children:'Then you must accept one thing: you can prove "others can\'t see it," but you cannot prove "who made them unable to see it."'}),"\n",(0,i.jsx)(t.h2,{id:"xiv-the-inversion-of-the-burden-of-proof",children:"XIV. The Inversion of the Burden of Proof"}),"\n",(0,i.jsx)(t.p,{children:"And this is where the real anger should be directed."}),"\n",(0,i.jsxs)(t.p,{children:["Not at being suppressed. Suppression can be identified, resisted, and written about. The real design is ",(0,i.jsx)(t.strong,{children:"making suppression and indifference evidentially indistinguishable"}),"."]}),"\n",(0,i.jsx)(t.p,{children:"In this design, the burden of proof is thoroughly inverted. The platform never claims your content is problematic, so it never needs to prove anything. But you must prove you've been suppressed \u2014 using a system deliberately designed to produce no evidence. You're being asked to submit a document that the system was designed never to generate."}),"\n",(0,i.jsx)(t.p,{children:'And "unprovability" is not a side-effect. It is a specification. It was written into that 2015 application as the core feature of the invention: "so that the user will not realise."'}),"\n",(0,i.jsx)(t.p,{children:"I once wrote that the system doesn't need to deny you \u2014 it only needs to file you."}),"\n",(0,i.jsx)(t.p,{children:"At the time, I thought that was a metaphor."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"sources",children:"Sources"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:'US Patent 10356024, "Moderating content in an online forum," filed February 2015, granted July 2019'}),"\n",(0,i.jsx)(t.li,{children:'Meta Transparency Center: "Reducing the Distribution of Problematic Content," "Types of Content We Demote," "How Facebook Group Feed Ranking Works"'}),"\n",(0,i.jsx)(t.li,{children:"Meta's EU DSA Transparency Report (Facebook)"}),"\n",(0,i.jsx)(t.li,{children:"EU Digital Services Act, Article 17"}),"\n",(0,i.jsx)(t.li,{children:"Reuters (Jeff Horwitz, Engen Tham), Meta scam advertising internal documents series, November 2025"}),"\n"]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"this-series",children:"This Series"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Attenuation: How Visibility Is Allocated"})," \u2014 Three Volumes"]}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Volume I"})," Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence (this article)"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Volume II"})," The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Volume III"})," One Like, One Point; One Flame War, Thirty Points \u2014 After the Forums Disappeared, Complexity Lost Its Place"]}),"\n",(0,i.jsx)(t.li,{children:"Criminal Investigation Bureau, Ministry of the Interior (Taiwan); Taiwan High Prosecutors Office: Investment fraud methods disclosure"}),"\n"]})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);const o={},s=i.createContext(o);function a(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);